package com.infrastructure.model;

import com.infrastructure.family.EnvironmentFamily;
import java.time.Instant;

/**
 * Report generated by the Factory Method creator (SensorDeploymentStation)
 * upon completing the deployment, verification, and calibration lifecycle.
 */
public record DeploymentReport<F extends EnvironmentFamily>(
        String sensorId,
        F family,
        Instant deployedAt,
        double initialCalibrationOffset,
        boolean selfTestPassed,
        String verificationChecksum,
        String auditLog
) {
}
